import { z } from 'zod';
import { DomainError, notImplemented, type UseCase, type UseCaseContext } from '@agentic-ddd/core';
import { AgentUseCase } from '@agentic-ddd/decorators';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

export const createTaskInput = z.object({ task_id: z.string().min(1), title: z.string().min(1) });
export const createTaskOutput = z.object({ task_id: z.string(), title: z.string(), status: z.literal('pending') });
export type CreateTaskInput = z.infer<typeof createTaskInput>;
export type CreateTaskOutput = z.infer<typeof createTaskOutput>;

@AgentUseCase({ name: 'create_task', description: 'Cria, salva e publica uma tarefa pendente; id repetido falha com TASK_ALREADY_EXISTS.', whenToUse: 'Quando o usuário deseja criar uma tarefa.', whenNotToUse: 'Para concluir tarefa existente.', input: createTaskInput, output: createTaskOutput, uses: ['method:Task.create'], emits: [TaskCreated] })
export class CreateTask implements UseCase<CreateTaskInput, CreateTaskOutput> {
  constructor(private readonly tasks: TaskRepository) {}
  async execute(input: CreateTaskInput, ctx: UseCaseContext): Promise<CreateTaskOutput> {
    const existing = await this.tasks.findById(input.task_id);
    if (existing) {
      throw new DomainError('TASK_ALREADY_EXISTS', 'A tarefa já existe.');
    }
    const task = Task.create(input.task_id, input.title);
    await this.tasks.save(task);
    await ctx.publish(task.pullEvents());
    return { task_id: task.id, title: task.title, status: 'pending' };






  }
}

import { expect, test } from 'bun:test';
import { DomainError, type DomainEvent, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CreateTask } from '../application/create-task';
import { TaskCreated } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

function setup() {
  const storage = new InMemoryTaskRepository();
  const calls: string[] = [];
  const published: DomainEvent[] = [];
  const tasks: TaskRepository = {
    async findById(id) {
      calls.push(`find:${id}`);
      return storage.findById(id);
    },
    async save(task) {
      calls.push(`save:${task.id}:${task.status}`);
      await storage.save(task);
    },
  };
  const ctx: UseCaseContext = {
    correlationId: 'correlation-1',
    causationId: 'causation-1',
    async publish(events) {
      calls.push('publish');
      published.push(...events);
    },
  };
  return { storage, calls, published, tasks, ctx, usecase: new CreateTask(tasks) };
}

test(covers([
  'usecase:create_task',
  'criterion:0001/persistencia-criacao',
], 'salva t1 pendente, publica TaskCreated e rejeita repetição com TASK_ALREADY_EXISTS'), async () => {
  const { storage, calls, published, ctx, usecase } = setup();
  expect(await storage.findById('t1')).toBeNull();

  const result = await usecase.execute({ task_id: 't1', title: '  Minha tarefa  ' }, ctx);

  expect(result).toEqual({ task_id: 't1', title: 'Minha tarefa', status: 'pending' });
  const saved = await storage.findById('t1');
  expect(saved).not.toBeNull();
  expect(saved!.id).toBe('t1');
  expect(saved!.title).toBe('Minha tarefa');
  expect(saved!.status).toBe('pending');
  expect(calls).toEqual(['find:t1', 'save:t1:pending', 'publish']);
  expect(published).toHaveLength(1);
  expect(published[0]).toBeInstanceOf(TaskCreated);
  expect(published[0]!.payload).toEqual({ taskId: 't1', title: 'Minha tarefa' });
  expect(saved!.pullEvents()).toEqual([]);

  const error = await usecase.execute({ task_id: 't1', title: 'Outro título' }, ctx).catch(error => error);

  expect(error).toBeInstanceOf(DomainError);
  expect(error).toHaveProperty('code', 'TASK_ALREADY_EXISTS');
  expect(calls).toEqual(['find:t1', 'save:t1:pending', 'publish', 'find:t1']);
  expect(published).toHaveLength(1);
  expect(await storage.findById('t1')).toBe(saved);
  expect(saved!.title).toBe('Minha tarefa');
  expect(saved!.status).toBe('pending');
});

test(covers(['usecase:create_task'], 'rejeita título em branco sem salvar ou publicar'), async () => {
  const { storage, calls, published, ctx, usecase } = setup();

  const error = await usecase.execute({ task_id: 't1', title: ' \t\n ' }, ctx).catch(error => error);

  expect(error).toBeInstanceOf(DomainError);
  expect(error).toHaveProperty('code', 'TASK_TITLE_REQUIRED');
  expect(calls).toEqual(['find:t1']);
  expect(await storage.findById('t1')).toBeNull();
  expect(published).toEqual([]);
});

test(covers(['usecase:create_task'], 'propaga falha ao salvar sem publicar TaskCreated'), async () => {
  const { storage, tasks, calls, published, ctx } = setup();
  const failure = new Error('Falha ao salvar');
  tasks.save = async task => {
    calls.push(`save:${task.id}:${task.status}`);
    throw failure;
  };

  const error = await new CreateTask(tasks).execute({ task_id: 't1', title: 'Minha tarefa' }, ctx).catch(error => error);

  expect(error).toBe(failure);
  expect(calls).toEqual(['find:t1', 'save:t1:pending']);
  expect(await storage.findById('t1')).toBeNull();
  expect(published).toEqual([]);
});
